package cart

// Item represents a product in the cart - minimal, as the tests demand
type Item struct {
	ID       string
	Name     string
	Price    float64
	Quantity int
}

// ShoppingCart holds items. It LIVES!
type ShoppingCart struct {
	items map[string]*Item
}

// NewShoppingCart creates a fresh specimen
func NewShoppingCart() *ShoppingCart {
	return &ShoppingCart{
		items: make(map[string]*Item),
	}
}

// AddItem introduces new... components
func (c *ShoppingCart) AddItem(id, name string, price float64, quantity int) {
	if existing, found := c.items[id]; found {
		existing.Quantity += quantity
		return
	}
	c.items[id] = &Item{
		ID:       id,
		Name:     name,
		Price:    price,
		Quantity: quantity,
	}
}

// RemoveItem excises the unwanted tissue
func (c *ShoppingCart) RemoveItem(id string) {
	delete(c.items, id)
}

// UpdateQuantity adjusts the... dosage
func (c *ShoppingCart) UpdateQuantity(id string, quantity int) {
	if item, found := c.items[id]; found {
		if quantity <= 0 {
			delete(c.items, id)
			return
		}
		item.Quantity = quantity
	}
}

// GetItem retrieves a specific specimen
func (c *ShoppingCart) GetItem(id string) *Item {
	return c.items[id]
}

// GetItems returns all items - the complete collection
func (c *ShoppingCart) GetItems() []*Item {
	result := make([]*Item, 0, len(c.items))
	for _, item := range c.items {
		result = append(result, item)
	}
	return result
}

// GetTotal calculates the sum - pure mathematics, no side effects
func (c *ShoppingCart) GetTotal() float64 {
	var total float64
	for _, item := range c.items {
		total += item.Price * float64(item.Quantity)
	}
	return total
}

// Clear empties the cart - a fresh start for new experiments
func (c *ShoppingCart) Clear() {
	c.items = make(map[string]*Item)
}

// ItemCount returns total items - quantity matters in reanimation
func (c *ShoppingCart) ItemCount() int {
	count := 0
	for _, item := range c.items {
		count += item.Quantity
	}
	return count
}

// IsEmpty checks if the cart lacks... subjects
func (c *ShoppingCart) IsEmpty() bool {
	return len(c.items) == 0
}
